// Model documentation (single source: docs/model/*.md) and references (docs/references.yaml).
import { marked } from 'marked';
import katex from 'katex';
import YAML from 'yaml';
import referencesRaw from '../../../docs/references.yaml?raw';

const files = import.meta.glob('../../../docs/model/*.md', {
  query: '?raw',
  import: 'default',
  eager: true,
});

// Figures referenced from the model docs as img/<name>.svg (generated by scripts/make_figures.py).
const images = Object.fromEntries(
  Object.entries(
    import.meta.glob('../../../docs/model/img/*.svg', { query: '?url', import: 'default', eager: true })
  ).map(([path, url]) => [`img/${path.split('/').pop()}`, url])
);

const references = YAML.parse(referencesRaw);
const refById = Object.fromEntries(references.map((r) => [r.id, r]));

function splitFrontMatter(src) {
  const m = src.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
  if (!m) return { meta: {}, body: src };
  return { meta: YAML.parse(m[1]), body: m[2] };
}

/** Render Markdown with $…$ / $$…$$ math (KaTeX, HTML + MathML for screen readers). */
export function renderMarkdown(src) {
  const math = [];
  const stash = (tex, display) => {
    math.push(
      katex.renderToString(tex, { displayMode: display, throwOnError: false, output: 'htmlAndMathml' })
    );
    return `\u0000M${math.length - 1}\u0000`;
  };
  // Protect inline code from math substitution.
  const code = [];
  let s = src.replace(/`[^`\n]*`/g, (c) => {
    code.push(c);
    return `\u0000C${code.length - 1}\u0000`;
  });
  s = s.replace(/\$\$([\s\S]+?)\$\$/g, (_, t) => stash(t, true));
  s = s.replace(/\$([^$\n]+?)\$/g, (_, t) => stash(t, false));
  s = s.replace(/\u0000C(\d+)\u0000/g, (_, i) => code[+i]);
  let html = marked.parse(s);
  html = html.replace(/\u0000M(\d+)\u0000/g, (_, i) => math[+i]);
  // Resolve figure paths to the bundled asset URLs.
  html = html.replace(/<img src="(img\/[^"]+)"/g, (m, src) => (images[src] ? `<img src="${images[src]}"` : m));
  return html;
}

export const docs = Object.fromEntries(
  Object.entries(files).map(([path, raw]) => {
    const id = path.split('/').pop().replace(/\.md$/, '');
    const { meta, body } = splitFrontMatter(raw);
    return [
      id,
      {
        id,
        meta,
        html: renderMarkdown(body),
        references: (meta.references || []).map((r) => refById[r]).filter(Boolean),
      },
    ];
  })
);
